import{_ as a,o as e,c as o,ag as d}from"./chunks/framework.CAXxHpAX.js";const s=JSON.parse('{"title":"守中","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-守中.md","filePath":"50-概念资料/dict-守中.md","lastUpdated":1778155802000}'),r={name:"50-概念资料/dict-守中.md"};function l(i,t,h,u,c,n){return e(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="守中" tabindex="-1">守中 <a class="header-anchor" href="#守中" aria-label="Permalink to &quot;守中&quot;">​</a></h1><blockquote><p>传统：道家 | 佛家对应：中道 | 儒家对应：中庸</p></blockquote><h2 id="了空居士的定义" tabindex="-1">了空居士的定义 <a class="header-anchor" href="#了空居士的定义" aria-label="Permalink to &quot;了空居士的定义&quot;">​</a></h2><p>&quot;守中&quot;就是<strong>看准最佳时机，以最客观的方式去做</strong>。不是停在中间不动，而是不走极端、不盲动、不妄动。了空居士比喻：&quot;就像开车，要不断微调方向才能保持在车道中间。&quot;</p><p>守中不是折中主义——&quot;中&quot;是最客观的判断点，是根据整体观找到的最佳行动方案。</p><h2 id="原话出处" tabindex="-1">原话出处 <a class="header-anchor" href="#原话出处" aria-label="Permalink to &quot;原话出处&quot;">​</a></h2><blockquote><p>&quot;多言数穷，不如守中。&#39;中&#39;就是最客观，看准最佳时机。&quot; — <a href="/60-原文段落/道德经5章-多言数穷不如守中">道德经5章-多言数穷不如守中</a></p></blockquote><blockquote><p>&quot;守中不是停在中间不动，是不走极端。就像开车，要不断微调方向。&quot;</p></blockquote><h2 id="常见误解" tabindex="-1">常见误解 <a class="header-anchor" href="#常见误解" aria-label="Permalink to &quot;常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody><tr><td>守中就是&quot;中立&quot;、谁也不得罪</td><td>守中是找到客观上最佳的方案，不是和稀泥</td></tr><tr><td>守中就是不行动</td><td>守中是不盲动不妄动，该动就动，看准最佳时机</td></tr></tbody></table><h2 id="跨传统对比" tabindex="-1">跨传统对比 <a class="header-anchor" href="#跨传统对比" aria-label="Permalink to &quot;跨传统对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>传统</th><th>对应概念</th><th>侧重</th></tr></thead><tbody><tr><td>道家</td><td>守中</td><td>客观判断，看准时机</td></tr><tr><td>佛家</td><td>中道</td><td>不执有，不执空</td></tr><tr><td>儒家</td><td>中庸</td><td>不偏不倚，恰到好处</td></tr></tbody></table><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-中道">dict-中道</a> — 守中是道家版的中道</li><li><a href="/50-概念资料/dict-无为">dict-无为</a> — 守中的行动就是不妄为</li><li><a href="/50-概念资料/dict-整体观">meta-整体观</a> — 守中要靠整体观来找准&quot;中&quot;</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-圆融中和">model-圆融中和</a> — 守中是圆融中和的核心操作</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><p>每次做判断时问自己&quot;我现在是不是在极端上？有没有第三种可能？&quot; 做决策前列出各方的利益，找到对整体最有利的方案。</p>',18)])])}const b=a(r,[["render",l]]);export{s as __pageData,b as default};
